using System.Collections.Generic;
using UnityEngine;
namespace FishSandbox {
 public class HarborWorld : MonoBehaviour {
  public Transform boat,shop,fire; public Light sun; public Material water,sky; public Vector3 boatImpulse; public float boatSpin; public float boatYaw;
  readonly Dictionary<Color,Material> mats=new(); public readonly List<Vector3> islands=new(){Vector3.zero,new Vector3(85,0,85),new Vector3(-95,0,110),new Vector3(115,0,-85)};
  public static Color Sand=new(.78f,.68f,.45f), Grass=new(.32f,.48f,.27f), Wood=new(.32f,.19f,.12f), Teal=new(.08f,.52f,.55f), Gold=new(1,.72f,.18f);
  public Material Mat(Color c){if(!mats.TryGetValue(c,out var m)){m=new Material(Shader.Find("Standard"));m.color=c;m.SetFloat("_Glossiness",.12f);mats[c]=m;}return m;}
  public GameObject Shape(string n,PrimitiveType type,Vector3 pos,Vector3 scale,Color c,Transform parent=null,bool solid=true){var o=GameObject.CreatePrimitive(type);o.name=n;o.transform.SetParent(parent,false);o.transform.localPosition=pos;o.transform.localScale=scale;o.GetComponent<Renderer>().sharedMaterial=Mat(c);if(!solid)Destroy(o.GetComponent<Collider>());return o;}
  public GameObject Box(string n,Vector3 p,Vector3 s,Color c,Transform parent=null,bool solid=true)=>Shape(n,PrimitiveType.Cube,p,s,c,parent,solid);
  public Transform Root(string n,Vector3 p,Transform parent=null){var t=new GameObject(n).transform;t.SetParent(parent,false);t.localPosition=p;return t;}
  public void Generate(){
   Random.InitState(4001890);RenderSettings.ambientLight=new Color(.65f,.74f,.8f);RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.0025f;RenderSettings.fogColor=new Color(.58f,.76f,.82f);
   sun=new GameObject("Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.25f;sun.transform.rotation=Quaternion.Euler(42,-35,0);sun.shadows=LightShadows.Soft;
   var sea=new GameObject("Ocean",typeof(MeshFilter),typeof(MeshRenderer));sea.transform.position=new Vector3(0,-.35f,0);sea.GetComponent<MeshFilter>().sharedMesh=OceanMesh();water=new Material(Shader.Find("FishSandbox/Ocean"));sea.GetComponent<Renderer>().sharedMaterial=water;sky=new Material(Shader.Find("FishSandbox/Sky"));RenderSettings.skybox=sky;
   for(int n=0;n<islands.Count;n++){var center=islands[n];Island(center,n==0?24:19,n);for(int i=0;i<16;i++){var p=center+new Vector3(Random.Range(-14,14),1.2f,Random.Range(-14,10));if(n==0&&Mathf.Abs(p.x)<6)continue;Tree(p,Random.Range(3.5f,6));}for(int i=0;i<12;i++){var a=i*Mathf.PI/6;Shape("Shore rock",PrimitiveType.Sphere,center+new Vector3(Mathf.Cos(a)*21,.15f,Mathf.Sin(a)*21),new Vector3(3,2,2),new Color(.38f,.43f,.43f));}}
   for(int i=0;i<23;i++){Box("Pier plank",new Vector3(0,.95f,15+i*.65f),new Vector3(4,.25f,.6f),i%3==0?new Color(.48f,.31f,.18f):Wood);if(i%4==0)for(int j=-1;j<=1;j+=2)Box("Pier pile",new Vector3(j*1.65f,-.4f,15+i*.65f),new Vector3(.22f,3,.22f),Wood);}
   shop=Root("Fish market",new Vector3(-7,1.1f,10));Box("Counter",new Vector3(0,.55f,0),new Vector3(5,1.1f,2),Wood,shop);for(int j=-1;j<=1;j+=2)Box("Post",new Vector3(j*2.2f,1.9f,0),new Vector3(.2f,4,.2f),Wood,shop);Box("Awning",new Vector3(0,3.5f,0),new Vector3(5.5f,.25f,3),Teal,shop);Sign("FISH MARKET",shop.position+new Vector3(0,2.7f,-1.25f),20);
   fire=Root("Campfire",new Vector3(7,1.15f,12));for(int i=0;i<7;i++){float a=i*Mathf.PI*2/7;Shape("Stone",PrimitiveType.Sphere,new Vector3(Mathf.Cos(a)*.9f,0,Mathf.Sin(a)*.9f),Vector3.one*.5f,Color.gray,fire);}Box("Logs",Vector3.zero,new Vector3(1.6f,.3f,.4f),Wood,fire);var flame=Shape("Flame",PrimitiveType.Sphere,new Vector3(0,.5f,0),new Vector3(.65f,1.2f,.65f),new Color(1,.4f,.08f),fire,false);var l=flame.AddComponent<Light>();l.color=new Color(1,.5f,.15f);l.range=7;l.intensity=2;
   boat=Root("Motor boat",new Vector3(5,.2f,29));Box("Hull",Vector3.zero,new Vector3(3,.6f,6),new Color(.82f,.7f,.47f),boat);Box("Floor",new Vector3(0,.4f,0),new Vector3(2.5f,.2f,5.4f),Wood,boat);for(int j=-1;j<=1;j+=2)Box("Gunwale",new Vector3(j*1.4f,.7f,0),new Vector3(.2f,.5f,6),Teal,boat);Box("Bow",new Vector3(0,.7f,2.8f),new Vector3(2.7f,.5f,.3f),Teal,boat);Box("Seat",new Vector3(0,.8f,-1.3f),new Vector3(2.6f,.2f,.6f),Wood,boat);Box("Motor",new Vector3(0,.4f,-3),new Vector3(.6f,1,.7f),new Color(.16f,.2f,.23f),boat);var wheel=Shape("Wheel",PrimitiveType.Cylinder,new Vector3(.5f,1.15f,.7f),new Vector3(.45f,.06f,.45f),Color.black,boat,false);wheel.transform.localRotation=Quaternion.Euler(65,0,0);
   Sign("WELCOME TO THE ARCHIPELAGO",new Vector3(0,3,9),22);Sign("EMBER ISLAND",islands[1]+new Vector3(0,4,0),24);Sign("THE REEF",islands[2]+new Vector3(0,4,0),24);
   for(int i=0;i<8;i++){var p=islands[1]+new Vector3(Random.Range(-8,8),2,Random.Range(-8,8));Shape("Volcanic rock",PrimitiveType.Sphere,p,new Vector3(6,Random.Range(4,9),6),new Color(.25f,.28f,.3f));}
  }
  Mesh OceanMesh(){int side=150;var vertices=new Vector3[(side+1)*(side+1)];var triangles=new int[side*side*6];for(int z=0;z<=side;z++)for(int x=0;x<=side;x++)vertices[z*(side+1)+x]=new Vector3((x-side/2)*5,0,(z-side/2)*5);int k=0;for(int z=0;z<side;z++)for(int x=0;x<side;x++){int a=z*(side+1)+x,b=a+1,c=a+side+1,d=c+1;triangles[k++]=a;triangles[k++]=c;triangles[k++]=b;triangles[k++]=b;triangles[k++]=c;triangles[k++]=d;}var m=new Mesh{name="Faceted sea"};m.vertices=vertices;m.triangles=triangles;m.RecalculateNormals();m.RecalculateBounds();return m;}
  void Island(Vector3 center,float radius,int seed){int count=40;var verts=new List<Vector3>();var tris=new List<int>();var colors=new List<Color>();for(int i=0;i<count;i++){float a=i*2*Mathf.PI/count,b=(i+1)*2*Mathf.PI/count;float ra=radius*(1+Mathf.Sin(i*3.1f+seed)*.08f),rb=radius*(1+Mathf.Sin((i+1)*3.1f+seed)*.08f);Vector3 p=new(Mathf.Cos(a)*ra,0,Mathf.Sin(a)*ra),q=new(Mathf.Cos(b)*rb,0,Mathf.Sin(b)*rb);Vector3[] face={new Vector3(0,1.1f,0),p*.73f+Vector3.up*1.1f,q*.73f+Vector3.up*1.1f,p*.73f+Vector3.up*1.1f,p,q,p*.73f+Vector3.up*1.1f,q,q*.73f+Vector3.up*1.1f};for(int j=0;j<face.Length;j++){tris.Add(verts.Count);verts.Add(face[j]);colors.Add(j<3?Grass:Sand);}}var mesh=new Mesh();mesh.SetVertices(verts);for(int k=0;k<tris.Count;k+=3){int swap=tris[k+1];tris[k+1]=tris[k+2];tris[k+2]=swap;}mesh.SetTriangles(tris,0);mesh.SetColors(colors);mesh.RecalculateNormals();var o=new GameObject("Island "+seed,typeof(MeshFilter),typeof(MeshRenderer),typeof(MeshCollider));o.transform.position=center;o.GetComponent<MeshFilter>().sharedMesh=mesh;o.GetComponent<MeshRenderer>().sharedMaterial=new Material(Shader.Find("FishSandbox/VertexColor"));o.GetComponent<MeshCollider>().sharedMesh=mesh;}
  void Tree(Vector3 p,float height){var root=Root("Palm",p);var trunk=Shape("Trunk",PrimitiveType.Cylinder,new Vector3(0,height*.5f,0),new Vector3(.35f,height*.5f,.35f),Wood,root);trunk.transform.localRotation=Quaternion.Euler(0,0,9);for(int i=0;i<6;i++){var leaf=Box("Palm frond",new Vector3(0,height,0),new Vector3(.8f,.12f,4),new Color(.19f,.38f,.22f),root,false);leaf.transform.localRotation=Quaternion.Euler(18,i*60,0);}}
  void Sign(string text,Vector3 pos,int size){var t=new GameObject(text).AddComponent<TextMesh>();t.text=text;t.fontSize=size;t.characterSize=.12f;t.anchor=TextAnchor.MiddleCenter;t.color=new Color(.95f,.91f,.73f);t.transform.position=pos;t.transform.rotation=Quaternion.Euler(0,180,0);}
  public Transform Fish(Vector3 p,float size,Color c,bool drip=false){var root=Root("Fish",p);Shape("Body",PrimitiveType.Sphere,Vector3.zero,new Vector3(.42f,.7f,1.4f)*size,c,root,false);var tail=Box("Tail",new Vector3(0,0,-.8f)*size,new Vector3(.13f,.7f,.55f)*size,c*.8f,root,false);tail.transform.localRotation=Quaternion.Euler(30,0,0);Box("Dorsal fin",new Vector3(0,.32f,-.05f)*size,new Vector3(.08f,.4f,.5f)*size,c*.7f,root,false);for(int j=-1;j<=1;j+=2){Shape("Eye",PrimitiveType.Sphere,new Vector3(j*.2f,.12f,.43f)*size,Vector3.one*.14f*size,Color.white,root,false);Shape("Pupil",PrimitiveType.Sphere,new Vector3(j*.25f,.12f,.46f)*size,Vector3.one*.07f*size,Color.black,root,false);}if(drip){Box("Gold crown",new Vector3(0,.6f,.3f)*size,new Vector3(.5f,.3f,.4f)*size,Gold,root,false);for(int i=0;i<3;i++)Box("Crown point",new Vector3((i-1)*.2f,.85f,.3f)*size,new Vector3(.1f,.25f,.4f)*size,Gold,root,false);}return root;}
  public void TickBoat(float throttle,float turn,bool driving,float speed){boatYaw+=turn*55*Time.deltaTime;boatYaw+=boatSpin*Time.deltaTime;boatSpin=Mathf.Lerp(boatSpin,0,Time.deltaTime*.7f);boat.rotation=Quaternion.Euler(Mathf.Sin(Time.time*1.3f)*1.3f,boatYaw,Mathf.Cos(Time.time)*1.5f);var next=boat.position+(boat.forward*(driving?throttle*9*speed:0)+boatImpulse)*Time.deltaTime;bool blocked=false;foreach(var island in islands)if(Vector2.Distance(new(next.x,next.z),new(island.x,island.z))<24)blocked=true;if(!blocked)boat.position=new Vector3(next.x,.2f+Mathf.Sin(Time.time*1.8f)*.1f,next.z);boatImpulse=Vector3.Lerp(boatImpulse,Vector3.zero,Time.deltaTime*.6f);}
 }
}

